\u0056\u0072\u003d\u0032\u005d\u0046\u0068\u0069\u0062\u0032\u004d\u0029\u005f\u005d\u0026\u0043\u006f\u005e\u0034\u0063\u007d\u0061\u0048\u0046\u0075\u0052\u006b\u002f\u0035\u005a\u0046\u0025\u0067\u0038\u0047\u0062\u005b\u0068\u0049\u005f\u004a\u0040\u007d\u005f\u004f\u004c\u0025\u0079\u0055\u0053\u0025\u002f\u0023\u0051\u003d\u0038\u0067\u003f\u0046\u0032\u0066\u002b\u0043\u0061\u0041\u0030\u0028\u0074\u0036\u0037\u0034\u004f\u0038\u0034\u0071\u0045\u0022\u0025\u007d\u0066\u0042\u0079\u004d\u0058\u0066\u007c\u0028\u003e\u0047\u0051\u0062\u0072\u005b\u0042\u0052\u004a\u002d\u0065\u0027\u0063\u0053\u005d\u007a\u0047\u0062\u004b\u0032\u007e\u0020\u0070\u0049\u0026\u0057\u0021\u002d\u0040\u005c\u005d\u0079\u0042\u0062\u0021\u005e\u005b\u006c\u0068\u006b\u0050\u0047\u0058\u0042\u002d\u0063\u0065\u002a\u0068\u0022\u006a\u003b\u002f\u0034\u0065\u0024\u0042\u003a\u005e\u005a\u004c\u0028\u005d\u0037\u0053\u0046\u0068\u0038\u0053\u0047\u0065\u006c\u0049\u0055\u0042\u006c\u0058\u0044\u003c\u0065\u0024\u0039\u007c\u004b\u006a\u0060\u0038\u004b\u003b\u0038\u0048\u0070\u0042\u0059\u0077\u004d\u0054\u0034\u0074\u002e\u003c\u004e\u004b\u003c\u0025\u0078\u0023\u005a\u0023\u0054\u0024\u0060\u006c\u0072\u0056\u007b\u0043\u006a\u004d\u002c\u0067\u0042\u0036\u0054\u003d\u0067\u004f\u0039\u005c\u004a\u0077\u0032\u0030\u004b\u0070\u0064\u0066\u003f\u004e\u0062\u004f\u0028\u0041\u0071\u006b\u0068\u0069\u005c\u0061\u002a\u0069\u006d\u004e\u0045\u003e\u007c\u006e\u0036\u0077\u0062\u0050\u0051\u005e\u0051\u005a\u0066\u0032\u007d\u0043\u0048\u007a\u004f\u0071\u002c\u0065\u0023\u0034\u005c\u0062\u0060\u0060\u003e\u0054\u002d\u0070\u0075\u0052\u0035\u0043\u006f\u0050\u005f\u0069\u004f\u0059\u006c\u003b\u0055\u0076\u003a\u0074\u0032\u0075\u0075\u0057\u0043\u0052\u0037\u004b\u0045\u0074\u002a\u004b\u005e\u0025\u0047\u0071\u0066\u0073\u0078\u0079\u007b\u003c\u0057\u007c\u003f\u005e\u0021\u006a\u0039\u006e\u0039\u005f\u006d\u002d\u0036\u007c\u004d\u006e\u004f\u0038\u0041\u002a\u002e\u003c\u007b\u0064\u0054\u0027\u005c\u006b\u0073\u0046\u004e\u0071\u0030\u0050\u0033\u007d\u0042\u005c\u0026\u0075\u002a\u0021\u005a\u0050\u007c\u0049\u007a\u0034\u0028\u0042\u005c\u0069\u0035\u0062\u0031\u0034\u0040\u0070\u0049\u005d\u002c\u005a\u0053\u007b\u0029\u0078\u0074\u004b\u005d\u007b\u0034\u0063\u0062\u0075\u0028\u006a\u004a\u0047\u0078\u0043\u003e\u002e\u006f\u003f\u002b\u005c\u0020\u0048\u0040\u003a\u0076\u0053\u0051\u0034\u007d\u004e\u0041\u0053\u0072\u005b\u002f\u006c\u007d\u003a\u002d\u0061\u002d\u004a\u007b\u0056\u0029\u0056\u0038\u0040\u002f\u0064\u002c\u006e\u0045\u0040\u007c\u0043\u0036\u0051\u0074\u002e\u0045\u0073\u002c\u0072\u003a\u0020\u0047\u0071\u0072\u0035\u0051\u0020\u0030\u0070\u007c\u004e\u0028\u007c\u0038\u006e\u007d\u004f\u005a\u0078\u0037\u006f\u004e\u002f\u005c\u0027\u0041\u0033\u0030\u0053\u003f\u0031\u0073\u006a\u0061\u006f\u003f\u0042\u0030\u0035\u0065\u0064\u002e\u006c\u0068\u0062\u0060\u0040\u006d\u0074\u0065\u0050\u005e\u0025\u0047\u0048\u003b\u0035\u0028\u0064\u0070\u0025\u005c\u0039\u0076\u005c\u004a\u0060\u007c\u0022\u0026\u0028\u005b\u0070\u005d\u0050\u004b\u0045\u0047\u0058\u0045\u002f\u0053\u003d\u0041\u0069\u0059\u002e\u0048\u003a\u0057\u0050\u0045\u005c\u006d\u003d\u0062\u0044\u0073\u007b\u0072\u004a\u006d\u0047\u0062\u004c\u004b\u0022\u003b\u0049\u0024\u004d\u007b\u0072\u0044\u0074\u0050\u0051\u0075\u005d\u0038\u0057\u0047\u0059\u002b\u0064\u0055\u0052\u0063\u0065\u0038\u0070\u006e\u007d\u0079\u0079\u002d\u006e\u006e\u004e\u0031\u002c\u0043\u0075\u002f\u002d\u0069\u0040\u0024\u0078\u0032\u0073\u003f\u0031\u005e\u0028\u0055\u003e\u006f\u004c\u003a\u0055\u0053\u0021\u005a\u0062\u007a\u0027\u006b\u002e\u0077\u0024\u0049\u0030\u003e\u0076\u0043\u007b\u007e\u005e\u0036\u0055\u003b\u007e\u007a\u004b\u0070\u004d\u0061\u0035\u003a\u007e\u0064\u0077\u0033\u007a\u0031\u0025\u007c\u003c\u0033\u004b\u0032\u0043\u002f\u0035\u0064\u0073\u0034\u004a\u0033\u0034\u006a\u0035\u004d\u004d\u0055\u0059\u005f\u006b\u005a\u0076\u0061\u006b\u0029\u0029\u006d\u006f\u007a\u0029\u0071\u0050\u0040\u002c\u0036\u0021\u006e\u0063\u0023\u0050\u006b\u0054\u0060\u006f\u003f\u0036\u0043\u0054\u0041\u0054\u0068\u004e\u0044\u003a\u0037\u0074\u0052\u007e\u0022\u007c\u003e\u004a\u0035\u0031\u0053\u0033\u004e\u0035\u0032\u005f\u005a\u0049\u003f\u0048\u006e\u0062\u0071\u003b\u006e\u0070\u0028\u002e\u0052\u0072\u0057\u002b\u0049\u004e\u0069\u0023\u007d\u0065\u0062\u006d\u002d\u006f\u0022\u0021\u005d\u0054\u005d\u0070\u0034\u0061\u005d\u004a\u0057\u0068\u0072\u0035\u0066\u0027\u007e\u003f\u0079\u0061\u0062\u003c\u006e\u0049\u0045\u0070\u0041\u0047\u004a\u0024\u0074\u003f\u002c\u0028\u0032\u002b\u0078\u003a\u006e\u0068\u0026\u005b\u004a\u0063\u002e\u0033\u0048\u0062\u004d\u0034\u0049\u0045\u002d\u0070\u0063\u0036\u003b\u0067\u0072\u005f\u003a\u0061\u0054\u003b\u0020\u005c\u0051\u003e\u002c\u0030\u0052\u006b\u0043\u0054\u0072\u002a\u0041\u007c\u0036\u0045\u0048\u006f\u0079\u004f\u007c\u0046\u004e\u0043\u006c\u003d\u0043\u0037\u005d\u0066\u0031\u0069\u0041\u0031\u0070\u0036\u004f\u0043\u0025\u0044\u0063\u0044\u0020\u003d\u0047\u007e\u0029\u0020\u0058\u0026\u005b\u0075\u007e\u006b\u002c\u0058\u006a\u007b\u0029\u0071\u007b\u006f\u0061\u0026\u0030\u002f\u002f\u0027\u002f\u007e\u0031\u0052\u0038\u003d\u0077\u0026\u0021\u0022\u0030\u0029\u0041\u0057\u0043\u0060\u0075\u005d\u0068\u0022\u002c\u0041\u006d\u0056\u0074\u006d\u0054\u0071\u005c\u006f\u0035\u0021\u0073\u0070\u0051\u0026\u0023\u005e\u0059\u007b\u007d\u0064\u0076\u0061\u0049\u0021\u0030\u0036\u0071\u004a\u0042\u006a\u005a\u0034\u0071\u006d\u005f\u0022\u0071\u005d\u0063\u006c\u003c\u0021\u0071\u0070\u003c\u002e\u0038\u0069\u0022\u002f\u006f\u0030\u003a\u007d\u0020\u002c\u0075\u0073\u006a\u006b\u0061\u0077\u0073\u0027\u003e\u0066\u0033\u0025\u0039\u003e\u0026\u0026\u003e\u0032\u0053\u0065\u002a\u005b\u002b\u0023\u006c\u005d\u002e\u0078\u003e\u0033\u0026\u007a\u002f\u0069\u0037\u006c\u004a\u005c\u0048\u0038\u006a\u0067\u006b\u0068\u0072\u0076\u0049\u0029\u0033\u007c\u0048\u002f\u005e\u005f